cypress_script:
describe('Test Cases Listing', () => {
  it('should display the test cases correctly', () => {
    cy.visit('https://automationexercise.com/test_cases');
    cy.get('h2').contains('Test Cases').should('be.visible');
    cy.get('a').contains('Test Case 1: Register User').should('be.visible');
    cy.get('a').contains('Test Case 2: Login User with correct email and password').should('be.visible');
  });

  it('should not navigate when clicking a test case link without expected action', () => {
    cy.visit('https://automationexercise.com/test_cases');
    cy.get('a').contains('Test Case 1: Register User').click();
    cy.url().should('eq', 'https://automationexercise.com/test_cases');
    cy.get('#collapse1').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Test Cases Listing', () => {
  test('should display the test cases correctly', async ({ page }) => {
    await page.goto('https://automationexercise.com/test_cases');
    await expect(page.locator('h2')).toHaveText('Test Cases');
    await expect(page.locator('a').withText('Test Case 1: Register User')).toBeVisible();
    await expect(page.locator('a').withText('Test Case 2: Login User with correct email and password')).toBeVisible();
  });

  test('should not navigate when clicking a test case link without expected action', async ({ page }) => {
    await page.goto('https://automationexercise.com/test_cases');
    await page.locator('a').withText('Test Case 1: Register User').click();
    await expect(page).toHaveURL('https://automationexercise.com/test_cases');
    await expect(page.locator('#collapse1')).toBeVisible();
  });
});
